53: /// The colour a ray sees: its scattered path attenuated by each material, the sky gradient when it
54: /// misses.
55: fn ray_colour(ray: &Ray, world: &dyn Hittable, rng: &mut Rng) -> Colour {
56:     let mut ray = *ray;
57:     let mut colour = Vec3::new(1.0, 1.0, 1.0);
58:     for _ in 0..MAX_BOUNCES {
59:         if let Some(hit) = world.hit(&ray, 0.001, f64::INFINITY) {
60:             match hit.material.scatter(&ray, &hit, rng) {
61:                 Some((attenuation, scattered)) => {
62:                     colour = colour * attenuation;
63:                     ray = scattered;
64:                 }
65:                 None => return Vec3::new(0.0, 0.0, 0.0),
66:             }
67:         } else {
68:             return colour * sky_colour(&ray);
69:         }
70:     }
71:     Vec3::new(0.0, 0.0, 0.0)
72: }
73: 
74: /// The sky gradient a ray sees when it misses the scene: white at the horizon, blue above.
75: fn sky_colour(ray: &Ray) -> Colour {
76:     let t = 0.5 * (ray.direction.unit().y + 1.0);
77:     Vec3::new(1.0, 1.0, 1.0) * (1.0 - t) + Vec3::new(0.5, 0.7, 1.0) * t
78: }
79: 
80: fn scene() -> HittableList {
81:     let mut world = HittableList::default();
82:     world.add(Box::new(Sphere::new(
83:         Vec3::new(0.0, 0.0, -1.0),
84:         0.5,
85:         Rc::new(Lambertian::new(Colour::new(0.7, 0.3, 0.3))),
86:     )));
87:     world.add(Box::new(Sphere::new(
88:         Vec3::new(0.0, -100.5, -1.0),
89:         100.0,
90:         Rc::new(Lambertian::new(Colour::new(0.8, 0.8, 0.8))),
91:     )));
92:     world.add(Box::new(Sphere::new(
93:         Vec3::new(0.85, -0.25, -1.3),
94:         0.25,
95:         Rc::new(Metal::new(Colour::new(0.8, 0.8, 0.8), 0.3)),
96:     )));
97:     world.add(Box::new(Sphere::new(
98:         Vec3::new(-1.1, 0.0, -1.5),
99:         0.5,
100:         Rc::new(Dielectric::new(1.5)),
101:     )));
102:     world.add(Box::new(Triangle::new(
103:         Vec3::new(0.6, 0.15, -1.0),
104:         Vec3::new(1.95, 0.15, -1.0),
105:         Vec3::new(1.275, 0.92, -1.0),
106:         Rc::new(Lambertian::new(Colour::new(0.7, 0.3, 0.3))),
107:     )));
108:     world
109: }
