111: /// Every pixel's colour, row by row from the top, each pixel averaging `samples` jittered rays, with
112: /// the share of finished rows reported on standard error.
113: fn render(width: usize, height: usize, samples: usize) -> Vec<Colour> {
114:     let world = scene();
115:     let camera = Camera::new(width as f64 / height as f64);
116:     let mut rng = Rng::new(SEED);
117:     let mut pixels = Vec::with_capacity(width * height);
118:     for row in (0..height).rev() {
119:         for column in 0..width {
120:             let mut pixel = Vec3::new(0.0, 0.0, 0.0);
121:             for _ in 0..samples {
122:                 let u = (column as f64 + rng.next_f64()) / width as f64;
123:                 let v = (row as f64 + rng.next_f64()) / height as f64;
124:                 pixel = pixel + ray_colour(&camera.ray(u, v), &world, &mut rng);
125:             }
126:             pixels.push(pixel / samples as f64);
127:         }
128:         let done = height - row;
129:         eprint!("\r{}%", done * 100 / height);
130:     }
131:     eprintln!();
132:     pixels
133: }
134: 
135: pub(crate) fn to_byte(channel: f64) -> u8 {
136:     (255.999 * channel.clamp(0.0, 1.0).sqrt()) as u8
137: }
138: 
139: fn write_ppm(
140:     out: &mut impl Write,
141:     width: usize,
142:     height: usize,
143:     pixels: &[Colour],
144: ) -> io::Result<()> {
145:     writeln!(out, "P3\n{width} {height}\n255")?;
146:     for pixel in pixels {
147:         writeln!(
148:             out,
149:             "{} {} {}",
150:             to_byte(pixel.x),
151:             to_byte(pixel.y),
152:             to_byte(pixel.z)
153:         )?;
154:     }
155:     Ok(())
156: }
157: 
158: /// Resolve the arguments into one set of settings before any rendering starts.
159: fn parse_args(args: &[String]) -> Result<Settings, String> {
160:     let mut width = DEFAULT_WIDTH;
161:     let mut height = DEFAULT_HEIGHT;
162:     let mut samples = DEFAULT_SAMPLES;
163:     let mut output = PathBuf::from(DEFAULT_OUTPUT);
164:     let mut explicit_format = None;
165: 
166:     let mut index = 0;
167:     while index < args.len() {
168:         let option = args[index].as_str();
169:         let value = || {
170:             args.get(index + 1)
171:                 .map(String::as_str)
172:                 .ok_or_else(|| format!("{option} needs a value"))
173:         };
174:         match option {
175:             "--width" => width = parse_dimension(option, value()?)?,
176:             "--height" => height = parse_dimension(option, value()?)?,
177:             "--samples" => {
178:                 let value = value()?;
179:                 let count = value
180:                     .parse::<usize>()
181:                     .map_err(|_| format!("--samples: {value:?} is not a whole number"))?;
182:                 if count < 1 {
183:                     return Err(format!("--samples: {value:?} is less than 1"));
184:                 }
185:                 samples = count;
186:             }
187:             "--output" => output = PathBuf::from(value()?),
188:             "--format" => {
189:                 explicit_format = Some(match value()? {
190:                     "png" => Format::Png,
191:                     "ppm" => Format::Ppm,
192:                     other => return Err(format!("--format: unrecognised format {other:?}")),
193:                 });
194:             }
195:             other => return Err(format!("unknown option {other:?}")),
196:         }
197:         index += 2;
198:     }
199: 
200:     let format = resolve_format(explicit_format, &output)?;
201:     Ok(Settings {
202:         width,
203:         height,
204:         samples,
205:         output,
206:         format,
207:     })
208: }
209: 
210: /// A pixel dimension, which must parse as a whole number of at least 2.
211: fn parse_dimension(option: &str, value: &str) -> Result<usize, String> {
212:     let dimension = value
213:         .parse::<usize>()
214:         .map_err(|_| format!("{option}: {value:?} is not a whole number"))?;
215:     if dimension < 2 {
216:         return Err(format!("{option}: {value:?} is less than 2"));
217:     }
218:     Ok(dimension)
219: }
220: 
221: /// An explicit format, or the one named by the output file's extension.
222: fn resolve_format(explicit: Option<Format>, output: &Path) -> Result<Format, String> {
223:     if let Some(format) = explicit {
224:         return Ok(format);
225:     }
226:     match output.extension().and_then(|extension| extension.to_str()) {
227:         Some("png") => Ok(Format::Png),
228:         Some("ppm") => Ok(Format::Ppm),
229:         _ => Err(format!(
230:             "{}: output name has no png or ppm extension and no --format is given",
231:             output.display()
232:         )),
233:     }
234: }
235: 
236: fn run(settings: &Settings) -> io::Result<()> {
237:     let pixels = render(settings.width, settings.height, settings.samples);
238:     let mut bytes = Vec::new();
239:     match settings.format {
240:         Format::Png => png::write_png(&mut bytes, settings.width, settings.height, &pixels)?,
241:         Format::Ppm => write_ppm(&mut bytes, settings.width, settings.height, &pixels)?,
242:     }
243:     fs::write(&settings.output, bytes)
244: }
245: 
246: fn main() {
247:     let args: Vec<String> = std::env::args().skip(1).collect();
248:     let settings = match parse_args(&args) {
249:         Ok(settings) => settings,
250:         Err(message) => {
251:             eprintln!("error: {message}");
252:             eprintln!("{USAGE}");
253:             std::process::exit(2);
254:         }
255:     };
256:     if let Err(error) = run(&settings) {
257:         eprintln!("error: {error}");
258:         std::process::exit(1);
259:     }
260: }
