8: /// A surface material: how an incoming ray scatters, or nothing when it is absorbed.
9: pub trait Material {
10:     /// The attenuation and the scattered ray, or nothing when the ray is absorbed.
11:     fn scatter(&self, ray_in: &Ray, hit: &HitRecord, rng: &mut Rng) -> Option<(Colour, Ray)>;
12: }
13: 
14: /// A diffuse material that scatters in a random direction around the normal.
15: pub struct Lambertian {
16:     pub albedo: Colour,
17: }
18: 
19: impl Lambertian {
20:     /// A diffuse material with the given albedo.
21:     pub fn new(albedo: Colour) -> Self {
22:         Lambertian { albedo }
23:     }
24: }
25: 
26: impl Material for Lambertian {
27:     fn scatter(&self, _ray_in: &Ray, hit: &HitRecord, rng: &mut Rng) -> Option<(Colour, Ray)> {
28:         let direction = hit.normal + random_unit_vector(rng);
29:         Some((self.albedo, Ray::new(hit.point, direction)))
30:     }
31: }
32: 
33: /// A metal material that reflects about the normal, blurred by a fuzz factor in 0..=1.
34: pub struct Metal {
35:     pub albedo: Colour,
36:     pub fuzz: f64,
37: }
38: 
39: impl Metal {
40:     /// A metal with the given albedo and a fuzz factor in 0..=1.
41:     pub fn new(albedo: Colour, fuzz: f64) -> Self {
42:         Metal { albedo, fuzz }
43:     }
44: }
45: 
46: impl Material for Metal {
47:     fn scatter(&self, ray_in: &Ray, hit: &HitRecord, rng: &mut Rng) -> Option<(Colour, Ray)> {
48:         let reflected = reflect(ray_in.direction.unit(), hit.normal);
49:         let scattered = reflected + random_unit_vector(rng) * self.fuzz;
50:         if scattered.dot(hit.normal) <= 0.0 {
51:             None
52:         } else {
53:             Some((self.albedo, Ray::new(hit.point, scattered)))
54:         }
55:     }
56: }
57: 
58: /// A glass that refracts by its refractive index and reflects by total internal reflection or
59: /// Schlick's approximation.
60: pub struct Dielectric {
61:     pub refractive_index: f64,
62: }
63: 
64: impl Dielectric {
65:     /// A glass with the given refractive index.
66:     pub fn new(refractive_index: f64) -> Self {
67:         Dielectric { refractive_index }
68:     }
69: }
70: 
71: impl Material for Dielectric {
72:     fn scatter(&self, ray_in: &Ray, hit: &HitRecord, rng: &mut Rng) -> Option<(Colour, Ray)> {
73:         let unit_direction = ray_in.direction.unit();
74:         let eta_ratio = if hit.front_face {
75:             1.0 / self.refractive_index
76:         } else {
77:             self.refractive_index
78:         };
79:         let cos_theta = (-unit_direction.dot(hit.normal)).min(1.0);
80:         let sin_theta = (1.0 - cos_theta * cos_theta).sqrt();
81:         let direction =
82:             if eta_ratio * sin_theta > 1.0 || rng.next_f64() < schlick(cos_theta, eta_ratio) {
83:                 reflect(unit_direction, hit.normal)
84:             } else {
85:                 refract(unit_direction, hit.normal, eta_ratio)
86:             };
87:         Some((Colour::new(1.0, 1.0, 1.0), Ray::new(hit.point, direction)))
88:     }
89: }
90: 
91: /// The mirror reflection of `v` about the normal `n`.
92: fn reflect(v: Vec3, n: Vec3) -> Vec3 {
93:     v - n * (2.0 * v.dot(n))
94: }
95: 
96: /// The refracted direction of a unit ray `v` crossing a surface with unit normal `n`, for the
97: /// ratio `eta_ratio` of the index the ray leaves to the index it enters.
98: fn refract(v: Vec3, n: Vec3, eta_ratio: f64) -> Vec3 {
99:     let cos_theta = (-v.dot(n)).min(1.0);
100:     let perpendicular = (v + n * cos_theta) * eta_ratio;
101:     let parallel = n * -(1.0 - perpendicular.dot(perpendicular)).max(0.0).sqrt();
102:     perpendicular + parallel
103: }
104: 
105: /// Schlick's approximation of the reflectance at `cosine` for index ratio `eta_ratio`.
106: fn schlick(cosine: f64, eta_ratio: f64) -> f64 {
107:     let r0 = (1.0 - eta_ratio) / (1.0 + eta_ratio);
108:     let r0 = r0 * r0;
109:     r0 + (1.0 - r0) * (1.0 - cosine).powi(5)
110: }
111: 
112: /// A random direction on the unit sphere, drawn by rejection sampling a point in the unit cube.
113: fn random_unit_vector(rng: &mut Rng) -> Vec3 {
114:     loop {
115:         let p = Vec3::new(
116:             2.0 * rng.next_f64() - 1.0,
117:             2.0 * rng.next_f64() - 1.0,
118:             2.0 * rng.next_f64() - 1.0,
119:         );
120:         let len_squared = p.dot(p);
121:         if len_squared > 1e-12 && len_squared <= 1.0 {
122:             return p.unit();
123:         }
124:     }
125: }
