1: //! Anything a ray can hit, and the record of where it hit.
2: 
3: use std::rc::Rc;
4: 
5: use crate::aabb::Aabb;
6: use crate::material::Material;
7: use crate::ray::Ray;
8: use crate::vec3::Vec3;
