10: /// Where a ray hit a surface: the distance along the ray, the point, the normal that always faces
11: /// against the ray, the face side, the texture coordinates and the material of the object.
12: pub struct HitRecord {
13:     pub t: f64,
14:     pub point: Vec3,
15:     /// Faces against the incoming ray.
16:     pub normal: Vec3,
17:     pub front_face: bool,
18:     #[allow(dead_code)]
19:     pub u: f64,
20:     #[allow(dead_code)]
21:     pub v: f64,
22:     pub material: Rc<dyn Material>,
23: }
24: 
25: impl HitRecord {
26:     /// A record for a hit by `ray` at `point`, with `outward_normal` facing away from the object.
27:     pub fn new(
28:         ray: &Ray,
29:         t: f64,
30:         point: Vec3,
31:         outward_normal: Vec3,
32:         u: f64,
33:         v: f64,
34:         material: Rc<dyn Material>,
35:     ) -> Self {
36:         let front_face = ray.direction.dot(outward_normal) < 0.0;
37:         HitRecord {
38:             t,
39:             point,
40:             normal: if front_face {
41:                 outward_normal
42:             } else {
43:                 -outward_normal
44:             },
45:             front_face,
46:             u,
47:             v,
48:             material,
49:         }
50:     }
51: }
52: 
53: pub trait Hittable {
