    # images
    for m in re.finditer(r'!\[([^\]]*)\]\(([^)]+)\)', text):
        alt, target = m.groups()
        if not alt.strip(): print(f'{f}: empty alt {target}')
        if not (pathlib.Path('.') / target.lstrip('/')).exists(): print(f'{f}: missing image {target}')
    # paragraph length
    for para in re.split(r'\n\s*\n', prose):
        p = ' '.join(para.split())
        if len(p) > 1000: print(f'{f}: long paragraph {len(p)} chars: {p[:60]!r}')

# first paragraph summaries for docs pages
for f in sorted(pathlib.Path('docs').glob('*.md')):
