    i = next(i for i,l in enumerate(lines) if l.startswith('# '))
    j = i+1
    while j < len(lines) and not lines[j].strip(): j += 1
    para = lines[j]
    words = len(re.findall(r"[A-Za-z0-9`'’\-]+", re.sub(r'\[[^]]*\]\([^)]*\)', 'X', para)))
    sent = len(re.findall(r'[.!?](\s|$)', para))
    print(f'{f}: {words} words, {sent} sentence(s): {para[:80]}')
